#include "sprite.h"
#include <cassert>
#include <initializer_list>
#include <cstdio>
int main(){pico_sprite brush;brush.paint(0,5,false);assert(brush.opaque(0)&&brush.pixels[0]==5);brush.paint(0,9,true,true);assert(!brush.opaque(0)&&brush.pixels[0]==5);brush.paint(0,9,false,true);assert(brush.opaque(0));brush.paint(0,9,false,true);assert(!brush.opaque(0));pico_sprite unchanged=brush;brush.paint(256,8,false);assert(!memcmp(&brush,&unchanged,sizeof brush));pico_sprite s;assert(s.empty());for(unsigned i=0;i<256;++i){s.pixels[i]=i;s.opaque(i,i%3);assert(s.opaque(i)==bool(i%3));}uint8_t data[pico_sprite::bytes];s.encode(data);pico_sprite t;assert(t.decode(data,sizeof data));assert(!memcmp(&s,&t,sizeof s));for(unsigned i=0;i<sizeof data;++i){data[i]^=1;pico_sprite previous=t;assert(!t.decode(data,sizeof data));assert(!memcmp(&previous,&t,sizeof t));data[i]^=1;}assert(!t.decode(data,sizeof data-1));char p[100];for(const char *bad:{"","../a.sprite","/a.sprite","a/b.sprite","a\\b.sprite","a:bad.sprite","x.lua"})assert(!pico_sprite::path(bad,p,sizeof p));assert(pico_sprite::path("DEMO.sprite",p,sizeof p)&&!strcmp(p,"sprites/DEMO.sprite"));assert(pico_sprite::rgb(255)==0xffffff);puts("PASS: sprite RGB332/transparency/CRC/truncation/path bounds and validation-before-application");}
